it('calls onError when a plain object is thrown ([validated by: any rejection inside the turn calls onError with an Error](../../specs/hal-engine-config-hooks/spec.md#L22))', async () => {
  let receivedError: Error | undefined;
  const hooks: OrchestratorHooks = {
    onError: async (_session, error) => {
      receivedError = error;
    },
  };

  const reason = {code: 503, detail: 'upstream down'};
  const orchestrator = createChatOrchestrator(createErrorProvider(reason), promptBuilder, undefined, {
    hooks,
  });

  const result = await orchestrator.processMessage(createSession('hello')).catch(e => e);

  expect({
    rejection: result,
    isError: receivedError instanceof Error,
    message: receivedError?.message,
    cause: receivedError?.cause,
  }).toEqual({
    rejection: reason,
    isError: true,
    message: '[object Object]',
    cause: reason,
  });
});

